// prettier: formats files with Prettier (its standalone build and plugins).
const prettier = require('standalone.js');
const plugins = ['babel', 'estree', 'typescript', 'postcss', 'markdown', 'html', 'yaml', 'graphql'].map((p) => require(`plugins/${p}.js`));
const usage = `usage: prettier [--write | --check] [options] file...
  (no flag)          print the formatted file
  -w, --write        format the files in place
  -c, --check        list files that are not formatted (exit 1 if any)
  --parser NAME      babel, typescript, css, scss, less, json, markdown, html, vue, yaml, graphql
  --stdin-filepath F format stdin as if it were the file F
  --print-width N  --tab-width N  --use-tabs  --single-quote  --no-semi  --trailing-comma all|es5|none
Options also come from .prettierrc (JSON) in the folder.`;
const opts = {};
let mode = 'print';
const files = [];
for (let i = 0; i < args.length; i++) {
  const a = args[i];
  if (a === '-h' || a === '--help') return print(usage);
  else if (a === '-v' || a === '--version') return print(prettier.version);
  else if (a === '-w' || a === '--write') mode = 'write';
  else if (a === '-c' || a === '--check' || a === '-l' || a === '--list-different') mode = 'check';
  else if (a === '--parser') opts.parser = args[++i];
  else if (a === '--stdin-filepath') opts.filepath = args[++i];
  else if (a === '--print-width') opts.printWidth = Number(args[++i]);
  else if (a === '--tab-width') opts.tabWidth = Number(args[++i]);
  else if (a === '--use-tabs') opts.useTabs = true;
  else if (a === '--single-quote') opts.singleQuote = true;
  else if (a === '--no-semi') opts.semi = false;
  else if (a === '--trailing-comma') opts.trailingComma = args[++i];
  else if (a.startsWith('-')) {
    console.error(`prettier: unknown option ${a}\n${usage}`);
    exit(2);
  } else files.push(a);
}
let config = {};
if (await fs.exists('.prettierrc')) {
  try {
    config = JSON.parse(await fs.readText('.prettierrc'));
  } catch {
    console.error('prettier: .prettierrc is not JSON; ignoring it');
  }
}
if (!files.length) {
  if (!stdin) return print(usage);
  if (!opts.parser && !opts.filepath) {
    console.error('prettier: formatting stdin needs --parser or --stdin-filepath');
    exit(2);
  }
  const outText = await prettier.format(stdin, { ...config, ...opts, plugins });
  return void console.log(outText.replace(/\n$/, ''));
}
let failed = 0;
let unformatted = 0;
for (const file of files) {
  try {
    const text = await fs.readText(file);
    const o = { ...config, ...opts, filepath: file, plugins };
    if (mode === 'check') {
      if (!(await prettier.check(text, o))) (unformatted++, print(file));
      continue;
    }
    const formatted = await prettier.format(text, o);
    if (mode === 'write') {
      if (formatted !== text) await fs.writeFile(file, formatted);
      print(`${file}${formatted === text ? ' (unchanged)' : ''}`);
    } else console.log(formatted.replace(/\n$/, ''));
  } catch (e) {
    failed++;
    console.error(`${file}: ${String(e?.message ?? e).split('\n')[0]}`);
  }
}
if (failed) exit(2);
if (unformatted) exit(1);

// marked: converts Markdown to HTML.
const { marked } = require('lib/marked.umd.js');
const usage = `usage: marked [file] [-o out.html] [--page] [--breaks] [--no-gfm]
  Reads the file (or stdin) and prints HTML, or writes it with -o.
  --page     a whole HTML page (with a title and simple styles), not a fragment`;
let input = null;
let output = null;
let page = false;
const o = { gfm: true, breaks: false };
for (let i = 0; i < args.length; i++) {
  const a = args[i];
  if (a === '-h' || a === '--help') return print(usage);
  else if (a === '-o' || a === '--output') output = args[++i];
  else if (a === '--page' || a === '-s' || a === '--standalone') page = true;
  else if (a === '--breaks') o.breaks = true;
  else if (a === '--no-gfm') o.gfm = false;
  else if (a.startsWith('-')) {
    console.error(`marked: unknown option ${a}\n${usage}`);
    exit(2);
  } else input = a;
}
const md = input ? await fs.readText(input) : stdin;
if (!md && !input) return print(usage);
let html = await marked.parse(md, o);
if (page) {
  const title = (/^#\s+(.+)$/m.exec(md)?.[1] ?? (input ?? 'Document')).replace(/[<&>"]/g, (c) => `&#${c.charCodeAt(0)};`);
  html = `<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>${title}</title>\n<style>body{font:16px/1.6 system-ui,sans-serif;max-width:46rem;margin:2rem auto;padding:0 1rem;color:#222}pre{background:#f4f4f4;padding:.75rem;overflow:auto}code{font-family:ui-monospace,monospace}table{border-collapse:collapse}td,th{border:1px solid #ccc;padding:.25rem .5rem}img{max-width:100%}@media (prefers-color-scheme:dark){body{background:#161616;color:#ddd}pre{background:#222}}</style>\n</head>\n<body>\n${html}</body>\n</html>\n`;
}
if (output) {
  await fs.writeFile(output, html);
  print(`wrote ${output}`);
} else console.log(html.replace(/\n$/, ''));

// yaml2json / json2yaml: converts between YAML and JSON (js-yaml).
const yaml = require('dist/js-yaml.min.js');
const toJson = args[0] === '--to-json';
const rest = args.slice(1);
const name = toJson ? 'yaml2json' : 'json2yaml';
const usage = `usage: ${name} [file] [-o out] ${toJson ? '[--indent N] [--compact]' : '[--indent N]'}\n  Reads the file (or stdin) and prints ${toJson ? 'JSON' : 'YAML'}, or writes it with -o.`;
let input = null;
let output = null;
let indent = 2;
for (let i = 0; i < rest.length; i++) {
  const a = rest[i];
  if (a === '-h' || a === '--help') return print(usage);
  else if (a === '-o' || a === '--output') output = rest[++i];
  else if (a === '--indent') indent = Number(rest[++i]) || 2;
  else if (a === '--compact') indent = 0;
  else if (a.startsWith('-')) {
    console.error(`${name}: unknown option ${a}\n${usage}`);
    exit(2);
  } else input = a;
}
const text = input ? await fs.readText(input) : stdin;
if (!text && !input) return print(usage);
let result;
try {
  if (toJson) {
    const docs = yaml.loadAll(text);
    result = JSON.stringify(docs.length === 1 ? docs[0] : docs, null, indent || undefined) + '\n';
  } else result = yaml.dump(JSON.parse(text), { indent, lineWidth: 100, noRefs: true });
} catch (e) {
  console.error(`${name}: ${String(e?.message ?? e)}`);
  exit(1);
}
if (output) {
  await fs.writeFile(output, result);
  print(`wrote ${output}`);
} else console.log(result.replace(/\n$/, ''));
